-- VEXLUST v0.1 / PostgreSQL
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,feed_url text,enabled boolean NOT NULL DEFAULT false,last_synced_at timestamptz);
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title_uk text NOT NULL,parent_id uuid REFERENCES categories(id));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title_uk text NOT NULL,description_uk text NOT NULL DEFAULT '',category_id uuid REFERENCES categories(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES suppliers(id),product_id uuid REFERENCES products(id),external_id text NOT NULL,sku text,cost_kopecks bigint NOT NULL CHECK(cost_kopecks>=0),stock_quantity int NOT NULL DEFAULT 0 CHECK(stock_quantity>=0),synced_at timestamptz NOT NULL DEFAULT now(),UNIQUE(supplier_id,external_id));
CREATE TABLE product_prices(product_id uuid PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,price_kopecks bigint NOT NULL CHECK(price_kopecks>0),currency char(3) NOT NULL DEFAULT 'UAH',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE,image_url text NOT NULL,alt_uk text NOT NULL DEFAULT '',sort_order int NOT NULL DEFAULT 0);
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number text UNIQUE NOT NULL,customer_phone text NOT NULL,customer_email text,shipping_method text NOT NULL,shipping_payload jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','awaiting_payment','paid','sent_to_supplier','shipped','completed','cancelled','refunded')),total_kopecks bigint NOT NULL CHECK(total_kopecks>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id uuid REFERENCES products(id),supplier_item_id uuid REFERENCES supplier_items(id),title_snapshot text NOT NULL,quantity int NOT NULL CHECK(quantity>0),unit_price_kopecks bigint NOT NULL CHECK(unit_price_kopecks>=0));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),provider text NOT NULL,provider_reference text UNIQUE,status text NOT NULL CHECK(status IN ('created','pending','succeeded','failed','refunded')),amount_kopecks bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fulfillment_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),supplier_id uuid NOT NULL REFERENCES suppliers(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','submitted','confirmed','rejected','shipped')),tracking_number text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,supplier_id));
